SUMMARY = [
 'Báo cáo trình bày phân tích nghiệp vụ và thiết kế kiến trúc microservices cho WattPrint, hệ thống theo dõi điện năng từng thiết bị trong gia đình chỉ từ một điểm đo tại aptomat tổng và đưa ra gợi ý tiết kiệm qua trợ lý Energy Copilot. Xuất phát từ chín quy tắc nghiệp vụ, nhóm phân rã hệ thống thành năm service độc lập gồm core, nilm, insight, copilot và text2sql theo ba tiêu chí: quyền sở hữu dữ liệu (data ownership), đặc thù tải (workload) và cô lập lỗi (fault isolation). Trong đó, service text2sql kế thừa một ứng dụng Text-to-SQL độc lập, nơi LLM chỉ lập kế hoạch truy vấn theo danh mục metric đã khai báo, còn câu lệnh SQL do bộ biên dịch (compiler) dựng.',
 'Năm service đứng sau một API Gateway (Envoy), mỗi service quản lý database riêng, gọi nhau đồng bộ theo đồ thị một chiều không tạo vòng và phát tán sự kiện bất đồng bộ qua RabbitMQ kết hợp mẫu Transactional Outbox/Inbox. Báo cáo ghi lại các phương án phân rã đã cân nhắc, lý do lựa chọn và những đánh đổi kỹ thuật mà nhóm chấp nhận. Phần đặc tả API chi tiết, thực nghiệm chịu lỗi có số liệu, triển khai và đánh giá sẽ trình bày ở các chương sau.',
]
KEYWORDS = "microservices, SOA, API Gateway, NILM, RabbitMQ, transactional outbox, Energy Copilot, Text-to-SQL, Qdrant."

