BODY = []
A = BODY.append

A(('h1', 'CHƯƠNG 1. GIỚI THIỆU'))
A(('h2', '1.1. Bối cảnh'))
A(('p', 'Tiền điện là khoản chi cố định hằng tháng của mọi gia đình, nhưng phần lớn người dùng chỉ biết tổng số tiền phải trả vào cuối kỳ mà không rõ thiết bị nào tiêu tốn bao nhiêu. Một thử nghiệm thực địa trên 45.000 hộ dân tại Việt Nam cho thấy chỉ cần gửi thông tin ước tính tiền điện theo ngày, nhóm nhận thông báo đã chủ động giảm tiêu thụ so với nhóm đối chứng [@ta]. Phản hồi kịp thời đủ để tạo thay đổi trong thói quen sinh hoạt, song để biết chính xác cần cắt giảm ở đâu, người dùng phải nắm được chi phí của từng thiết bị. Khảo sát của Attari và cộng sự tại Mỹ chỉ ra rằng người tiêu dùng thường ước tính thấp điện năng của thiết bị khoảng 2,8 lần, và sai lệch nặng nhất lại rơi đúng vào nhóm thiết bị ngốn nhiều điện nhất [@attari].'))
A(('p', 'Các công cụ hiện có trên thị trường vẫn để trống nhu cầu này. Ứng dụng chăm sóc khách hàng của EVN mới dừng ở mức hiển thị sản lượng điện theo ngày của cả hộ [@sggp]. Nếu tự lắp ổ cắm thông minh để đo riêng từng thiết bị, mỗi ổ có giá khoảng 235.000 đồng [@tuya]. Một gia đình muốn theo dõi khoảng 10 điểm đo kèm bộ điều khiển trung tâm [@ha] phải bỏ ra từ 4 đến 10 triệu đồng, tự đấu nối và cấu hình mạng, trong khi ổ cắm rời vẫn không thể đo các phụ tải đấu thẳng vào đường dây âm tường như điều hòa hay bình nóng lạnh.'))
A(('p', 'Bài toán đặt ra cho dự án là tìm cách ước tính điện năng của từng thiết bị trong nhà với chi phí phần cứng thấp hơn nhiều. Nhóm lựa chọn kỹ thuật Non-Intrusive Load Monitoring (NILM) do Hart đề xuất năm 1992 [@hart]: chỉ lắp một cảm biến duy nhất đo tổng công suất tại aptomat chính, sau đó dùng mô hình học máy phân rã đường cong tổng thành công suất của từng thiết bị.'))
A(('h2', '1.2. Giải pháp WattPrint'))
A(('p', 'WattPrint giải quyết bài toán trên qua bốn khối chức năng nối tiếp nhau, biến chuỗi công suất thô tại aptomat thành thông tin chi phí và khuyến nghị hành động cụ thể:'))
A(('ol', [
 'Khối tách phụ tải (NILM) vận hành mô hình NILMFormer [@nilmformer] dựa trên kiến trúc Transformer, cho phép bóc tách tín hiệu thiết bị ngay cả khi công suất tổng biến động thất thường, kết hợp bước hiệu chỉnh (calibration) theo đặc thù thiết bị của từng hộ.',
 'Khối dashboard và hóa đơn tổng hợp sản lượng điện của từng thiết bị theo giờ, ngày, tuần, tháng và quy đổi trực tiếp ra tiền đồng theo biểu giá điện sinh hoạt 5 bậc hiện hành.',
 'Khối phân tích và dự báo phát hiện thiết bị chạy quá thời gian thông thường, nhận diện phụ tải chạy ngầm (standby), đối chiếu mức tiêu thụ với tháng trước hoặc nhóm hộ tương đồng, đồng thời dự báo hóa đơn cuối tháng và thời điểm chạm bậc giá kế tiếp.',
 'Khối Energy Copilot là trợ lý AI tương tác hai chiều: vừa giải đáp câu hỏi của người dùng (pull), vừa chủ động gửi gợi ý tiết kiệm khi phát hiện bất thường (push). Mọi con số trong câu trả lời đều do các công cụ tính toán xác định từ dữ liệu thực của hộ, còn LLM chỉ làm nhiệm vụ diễn giải. Với các câu hỏi tự do về số liệu, hệ thống chuyển qua công cụ Text-to-SQL theo cơ chế an toàn: LLM chỉ chọn metric và cột đã khai báo trong catalog, còn câu lệnh SQL do bộ biên dịch (compiler) dựng. Copilot cũng hỗ trợ lập kế hoạch tiết kiệm và đo kiểm kết quả trước, sau khi áp dụng.',
]))
A(('p', 'Về mức tiết kiệm kỳ vọng, các tổng hợp nghiên cứu quốc tế ghi nhận phản hồi chi tiết về điện năng giúp hộ gia đình giảm khoảng 2-4% sản lượng tiêu thụ [@buckley], trong khi thử nghiệm trên khoảng 1.000 hộ tại Đà Nẵng đạt mức giảm 4-7% [@nguyen]. Nhóm dùng các số liệu công bố này làm mốc tham chiếu cho thiết kế, chưa phải kết quả đo thực địa của WattPrint.'))
A(('h2', '1.3. Phạm vi của bài tập lớn'))
A(('p', 'Trước học phần này, nhóm đã phát triển backend WattPrint dưới dạng một ứng dụng FastAPI nguyên khối (monolith) chứa đầy đủ các phân hệ dữ liệu. Mục tiêu của bài tập lớn là phân rã kiến trúc monolith đó thành hệ thống hướng dịch vụ (microservices) có khả năng chịu lỗi và triển khai độc lập. Phạm vi thực hiện của báo cáo bao gồm:'))
A(('ul', [
 'Thiết kế năm service nghiệp vụ đứng sau một API Gateway, tách biệt cơ sở dữ liệu theo từng service, tích hợp dịch vụ định danh, message broker và vector store. Mỗi service có Dockerfile riêng và toàn bộ môi trường demo được đóng gói bằng Docker Compose.',
 'Tích hợp một ứng dụng Text-to-SQL độc lập có sẵn (`ai-agent-superset-standalone`) thành service `text2sql` của hệ thống: bổ sung cơ chế truyền định danh người hỏi từ `copilot`, khóa phạm vi dữ liệu theo từng hộ gia đình và khai báo bộ metric năng lượng.',
 'Đóng gói service `nilm` chuyên chạy inference với trọng số NILMFormer đã huấn luyện sẵn. Quy trình huấn luyện và đánh giá sai số của mô hình học máy nằm ngoài phạm vi kiến trúc phần mềm của báo cáo này.',
 'Sử dụng bộ dữ liệu công khai REFIT [@refit] phát lại (replay) qua cổng API Gateway để giả lập luồng dữ liệu từ cảm biến phần cứng thực tế (mục 2.5).',
 'Giữ nguyên hai ứng dụng phía người dùng (mobile app Expo và web Next.js), chỉ cấu hình lại điểm cuối API trỏ về cổng Gateway.',
]))
A(('h2', '1.4. Yêu cầu của đề bài'))
A(('p', 'Đề bài học phần yêu cầu xây dựng một hệ thống theo kiến trúc microservices đứng sau API Gateway và đóng gói hoàn toàn bằng container. Với quy mô nhóm ba sinh viên, hệ thống phải có tối thiểu ba service nghiệp vụ không tính gateway, mỗi service quản lý mã nguồn và kho dữ liệu riêng, công bố ít nhất bốn REST endpoint kèm tài liệu OpenAPI. Giao tiếp đồng bộ giữa các service phải cấu hình timeout và retry, đồng thời phải có ít nhất một luồng nghiệp vụ đi qua từ hai service trở lên xử lý được tình huống lỗi xảy ra giữa chừng. Ở bước kiểm chứng, nhóm cần xây dựng bộ kiểm thử Postman và thực nghiệm tối thiểu hai kịch bản lỗi có bảng số liệu đo đạc trước và sau khi bật cơ chế chịu lỗi (fault tolerance).'))
A(('p', 'Nhóm lựa chọn thực hiện thêm cả bốn hạng mục điểm cộng của đề bài: truyền sự kiện bất đồng bộ qua RabbitMQ với consumer đảm bảo idempotent và có DLQ, xác thực tập trung bằng JWT tại tầng gateway, trang bị circuit breaker cùng bulkhead cho các lời gọi liên service, và thiết lập quy trình CI chạy kiểm thử tự động. Cách các yêu cầu này chi phối quyết định thiết kế được phân tích xuyên suốt ở Chương 3 và Chương 4.'))
A(('h2', '1.5. Cấu trúc báo cáo'))
A(('p', 'Nội dung còn lại của báo cáo gồm ba chương. Chương 2 phân tích miền nghiệp vụ, xác định các tác nhân tương tác, sáu nhóm chức năng, chín quy tắc nghiệp vụ, năm yêu cầu phi chức năng và cơ chế phát lại dữ liệu cảm biến. Chương 3 trình bày thiết kế kiến trúc theo mô hình C4 từ bước chọn tiêu chí phân rã service, sơ đồ triển khai container, cơ chế giao tiếp đồng bộ và bất đồng bộ, xử lý luồng đa bước, cô lập dữ liệu, bảo mật tại gateway cho tới cấu trúc component bên trong từng service. Chương 4 tổng hợp các đánh đổi kỹ thuật và phương án kiểm soát rủi ro. Các chương về đặc tả API chi tiết, số liệu thực nghiệm chịu lỗi, triển khai và đánh giá sẽ được hoàn thiện ở giai đoạn tiếp theo của đồ án.'))

A(('h1', 'CHƯƠNG 2. PHÂN TÍCH NGHIỆP VỤ'))
A(('h2', '2.1. Người dùng và các bên liên quan'))
A(('p', 'Hệ thống WattPrint phục vụ hai nhóm người dùng trực tiếp, nhận luồng công suất tự động từ cảm biến gắn tại tủ điện và giao tiếp với năm hệ thống bên ngoài. Bảng 2.1 phân loại vai trò cùng luồng tương tác của từng đối tượng.'))
A(('table', 'Bảng 2.1. Người dùng, nguồn dữ liệu và hệ thống bên ngoài', ['Đối tượng', 'Vai trò', 'Tương tác chính'], [
 ['Thành viên hộ gia đình', 'Người dùng cuối. Chủ hộ khởi tạo hồ sơ nhà và cấp mã mời thành viên', 'Theo dõi điện năng từng thiết bị, tra cứu hóa đơn, nhận cảnh báo. Đặt câu hỏi cho Energy Copilot và nhận gợi ý tiết kiệm qua push notification'],
 ['Nhóm vận hành', 'Quản trị viên hệ thống WattPrint', 'Quản lý hồ sơ hộ, công tơ, phiên bản model NILM và danh mục metric của Text-to-SQL. Giám sát log, xử lý message trong DLQ và nhận cảnh báo hạ tầng qua Telegram'],
 ['Sensor ở aptomat (REFIT replayer trong đồ án)', 'Nguồn cấp dữ liệu đo tự động', 'Định kỳ đẩy từng batch mẫu đo công suất tổng lên hệ thống qua HTTPS, xác thực bằng API key riêng của thiết bị'],
 ['Nhà cung cấp LLM', 'Hệ thống ngoài', 'Sinh câu trả lời tự nhiên, điều phối tool calling, lập kế hoạch truy vấn cho Text-to-SQL và tạo vector embedding. Chỉ nhận prompt đã che PII'],
 ['Open-Meteo', 'Hệ thống ngoài', 'Cung cấp chuỗi nhiệt độ và độ ẩm ngoài trời theo giờ để hiệu chỉnh phân tích phụ tải và gợi ý sử dụng điều hòa'],
 ['Expo Push, Telegram', 'Hệ thống ngoài', 'Chuyển tiếp thông báo đẩy tới điện thoại của thành viên hộ và gửi cảnh báo vận hành cho quản trị viên'],
 ['Google Identity', 'Hệ thống ngoài', 'Xác thực đăng nhập bằng tài khoản Google theo chuẩn OIDC thông qua Keycloak'],
], [2400, 2600, 4071]))
A(('h2', '2.2. Các nhóm nghiệp vụ'))
A(('p', 'Nhóm chia miền nghiệp vụ của WattPrint thành sáu nhóm chức năng nối tiếp nhau theo vòng đời của dữ liệu, bắt đầu từ bước khai báo hộ gia đình cho tới khi sinh ra khuyến nghị tiết kiệm cá nhân hóa (Bảng 2.2). Sự phân tách giữa sáu nhóm này là cơ sở để vạch ranh giới các service ở Chương 3.'))
A(('table', 'Bảng 2.2. Sáu nhóm nghiệp vụ của WattPrint', ['Nhóm', 'Nội dung', 'Dữ liệu tạo ra'], [
 ['1. Quản lý hộ gia đình và thiết bị', 'Khởi tạo hồ sơ hộ, mời thành viên bằng mã dùng một lần, ghép nối công tơ, khai báo danh mục thiết bị theo phòng', 'Hồ sơ hộ, thành viên, công tơ, thiết bị'],
 ['2. Ingest dữ liệu sensor', 'Đón nhận batch mẫu đo công suất tổng từ công tơ, kiểm tra tính liên tục và ghi nhận chuỗi thời gian', 'Chuỗi công suất tổng theo thời gian, lịch sử batch'],
 ['3. Tách điện năng (NILM)', 'Chạy inference ước tính công suất từng thiết bị từ đường cong tổng, hiệu chỉnh theo hộ, quản lý phiên bản model', 'Chuỗi công suất ước tính từng thiết bị, nhật ký lần chạy inference'],
 ['4. Tính hóa đơn', 'Tổng hợp sản lượng kWh theo giờ, ngày, tháng và tính tiền điện theo biểu giá bậc thang', 'Hóa đơn kỳ, chi tiết tiền theo thiết bị, phiên bản biểu giá'],
 ['5. Phân tích và dự báo', 'Phát hiện thiết bị chạy bất thường hoặc tiêu thụ ngầm, dự báo hóa đơn và bậc giá, quản lý ngân sách, so sánh nhóm hộ tương đồng, mô phỏng what-if, đo kiểm M&V', 'Cảnh báo, bản ghi dự báo, thống kê nhóm, đường cơ sở M&V'],
 ['6. Trợ lý Copilot', 'Hỏi đáp ngôn ngữ tự nhiên, truy vấn số liệu tự do qua Text-to-SQL, gợi ý chủ động, lập kế hoạch tiết kiệm, điều phối thông báo và học từ phản hồi người dùng', 'Lịch sử hội thoại, gợi ý, kho tri thức RAG, catalog metric'],
], [2300, 4571, 2200]))
A(('p', 'Dữ liệu chảy xuyên suốt từ trên xuống dưới Bảng 2.2. Cảm biến tại aptomat gửi từng batch công suất tổng lên hệ thống để lưu trữ, bóc tách ra điện năng của từng thiết bị và quy đổi thành tiền trên hóa đơn (nhóm 2 đến nhóm 4). Chuỗi tiêu thụ đã tách tiếp tục làm đầu vào cho các thuật toán phát hiện bất thường và dự báo chi phí (nhóm 5), trước khi trợ lý Copilot tổng hợp kết quả phân tích để giải đáp hoặc chủ động khuyến nghị người dùng (nhóm 6). Trên toàn bộ đường đi này có hai điểm chuyển tiếp vượt qua ranh giới nhiều service và đòi hỏi tính nhất quán cao: bước nhận dữ liệu đo rồi gọi tách phụ tải NILM (nhóm 2 sang nhóm 3), và bước người dùng kích hoạt kế hoạch tiết kiệm cần thiết lập đồng thời đường cơ sở M&V lẫn hạn mức ngân sách (nhóm 6 sang nhóm 5). Mục 3.6 trình bày thiết kế xử lý lỗi giữa chừng cho hai điểm nối này.'))
A(('h2', '2.3. Quy tắc nghiệp vụ'))
A(('p', 'Để ranh giới trách nhiệm giữa các service rõ ràng và kiểm thử được, nhóm chỉ đưa vào thiết kế chín quy tắc nghiệp vụ có thể kiểm chứng trực tiếp bằng mã nguồn (Bảng 2.3). Mọi request vi phạm quy tắc đều bị service sở hữu từ chối ngay với mã trạng thái 4xx kèm nguyên nhân cụ thể, hoặc được chuyển sang nhánh xử lý dự phòng.'))
A(('table', 'Bảng 2.3. Quy tắc nghiệp vụ', ['Mã', 'Quy tắc', 'Lý do'], [
 ['BR1', 'Mỗi tài khoản chỉ thuộc tối đa một hộ (`home`). Thành viên mới gia nhập bằng mã mời chỉ dùng một lần và có hạn sử dụng', 'Ngăn một tài khoản truy cập chéo dữ liệu nhiều nhà. Hạn chế rủi ro khi mã mời bị lộ ra ngoài'],
 ['BR2', 'Mỗi công tơ chỉ ghép nối với một hộ qua mã pairing dùng một lần. Hệ thống chỉ nhận dữ liệu đo từ công tơ đã ghép nối hợp lệ kèm API key của thiết bị', 'Bảo đảm mọi chuỗi công suất gửi lên đều gắn định danh chính xác với một hộ gia đình'],
 ['BR3', 'Batch mẫu đo gửi lên phải idempotent và liên tục theo thời gian: trùng `Idempotency-Key` không ghi lặp dữ liệu, khoảng thời gian của batch mới không được hở hoặc chồng lấp với batch liền trước', 'Tránh làm sai lệch sản lượng kWh khi cảm biến gửi lặp gói tin do mạng chập chờn'],
 ['BR4', 'Tiền điện tính theo biểu giá sinh hoạt 5 bậc, áp dụng đúng phiên bản biểu giá đang có hiệu lực tại kỳ lập hóa đơn', 'Giữ nguyên số tiền của các kỳ hóa đơn đã chốt khi nhà nước điều chỉnh biểu giá mới'],
 ['BR5', 'Dự báo hóa đơn yêu cầu tối thiểu 7 ngày dữ liệu, so sánh hộ tương đồng cần ít nhất 10 hộ trong nhóm, đo kiểm M&V cần tối thiểu 14 ngày. Chưa đủ dữ liệu thì trả lỗi 422 kèm lý do', 'Ngăn hệ thống đưa ra con số dự báo thiếu căn cứ thống kê và bảo vệ tính ẩn danh khi so sánh giữa các hộ'],
 ['BR6', 'Tính năng Energy Copilot chỉ mở cho hộ đăng ký gói thuê bao Pro. Hộ dùng gói thường vẫn truy cập đầy đủ dashboard và các báo cáo phân tích', 'Thực thi trực tiếp mô hình kinh doanh hai gói thuê bao của sản phẩm'],
 ['BR7', 'Thông báo gợi ý chủ động không vượt quá N lần mỗi ngày (N cấu hình được) và không phát vào khung giờ nghỉ (`quiet hours`). Loại gợi ý bị người dùng từ chối sẽ tự động giảm điểm ưu tiên ở các lần xếp hạng sau', 'Tránh làm phiền người dùng bằng các thông báo dồn dập hoặc lặp lại khuyến nghị không phù hợp'],
 ['BR8', 'Mọi con số xuất hiện trong câu trả lời của Copilot đều phải lấy từ kết quả chạy tool trên dữ liệu của hộ, LLM chỉ diễn giải. Câu trả lời sai lệch số liệu, sai đơn vị hoặc thiếu trích dẫn nguồn sẽ bị chặn trước khi trả về', 'Loại bỏ hiện tượng ảo giác (hallucination) của LLM đối với số liệu tiền điện và công suất'],
 ['BR9', 'Thông tin định danh cá nhân (PII) phải được che trước khi gửi prompt ra nhà cung cấp LLM bên ngoài. Copilot và công cụ truy vấn chỉ được phép đọc dữ liệu thuộc đúng hộ của người đang hỏi', 'Bảo vệ quyền riêng tư của gia đình và cô lập tuyệt đối dữ liệu giữa các hộ thuê bao'],
], [800, 5071, 3200]))
A(('p', 'Nhìn vào chín quy tắc trên có thể thấy rõ sự phân cụm dữ liệu. Các quy tắc từ BR1 đến BR4 bảo vệ tính toàn vẹn của dữ liệu gốc (hồ sơ hộ, công tơ, chuỗi mẫu đo, hóa đơn) nên cần tập trung về một nguồn dữ liệu gốc (`source of truth`) duy nhất. Quy tắc BR5 đặt ngưỡng an toàn cho các thuật toán thống kê và dự báo. Trong khi đó, nhóm quy tắc từ BR6 đến BR9 kiểm soát quyền truy cập gói thuê bao, tần suất tương tác, kiểm duyệt đầu ra AI và cô lập dữ liệu truy vấn, được thực thi phối hợp giữa hai service `copilot` và `text2sql`. Chương 3 dựa trực tiếp vào ba cụm quy tắc này để phân rã hệ thống.'))
A(('h2', '2.4. Yêu cầu phi chức năng'))
A(('p', 'Bên cạnh chức năng nghiệp vụ, bài toán theo dõi năng lượng hộ gia đình và điều kiện làm việc của nhóm đặt ra năm yêu cầu phi chức năng (Bảng 2.4). Các ràng buộc này quyết định việc chọn mẫu giao tiếp, cơ chế lưu trữ và cách đóng gói container ở phần thiết kế.'))
A(('table', 'Bảng 2.4. Yêu cầu phi chức năng và ảnh hưởng đến kiến trúc', ['Yêu cầu', 'Diễn giải', 'Ảnh hưởng đến kiến trúc'], [
 ['Không mất, không trùng dữ liệu đo', 'Cảm biến ngoài thực tế thường gửi lại batch khi mất kết nối Wi-Fi. Sai số ở tầng thu thập sẽ làm lệch toàn bộ hóa đơn và phân tích phía sau', 'Kiểm tra `Idempotency-Key` và tính liên tục của batch, lưu dữ liệu kèm sự kiện trong cùng một giao dịch cơ sở dữ liệu (Transactional Outbox)'],
 ['Cô lập lỗi giữa các thành phần', 'Nhà cung cấp LLM phản hồi chậm hoặc mô hình NILM quá tải CPU không được làm nghẽn luồng nhận dữ liệu từ công tơ hay làm đơ màn hình dashboard', 'Tách riêng các thành phần có đặc thù lỗi khác nhau thành service độc lập. Áp dụng timeout, retry, circuit breaker và trạng thái chờ (`PENDING`)'],
 ['Bảo mật và quyền riêng tư', 'Đường cong công suất theo phút phản ánh rõ giờ giấc sinh hoạt và sự hiện diện của thành viên trong nhà', 'Xác thực JWT tập trung tại gateway. Ẩn PII trước khi gọi LLM. Phân tách mỗi service một database với tài khoản (DB role) riêng'],
 ['Khởi chạy trọn vẹn trên một máy để demo', 'Đề bài yêu cầu trình diễn trực tiếp toàn bộ hệ thống microservices trên máy cá nhân', 'Mỗi service có Dockerfile cùng endpoint `/health`, `/ready`. Gom các thành phần nền vào chung process của service để giữ tổng số container ở mức 10'],
 ['Phù hợp năng lực vận hành của nhóm ba người', 'Mỗi ngôn ngữ lập trình hay hệ quản trị dữ liệu thêm vào đều kéo theo chi phí cấu hình, viết migration và gỡ lỗi', 'Thống nhất dùng Python cho toàn bộ các service backend, gom mã dùng chung vào một thư viện nội bộ và ưu tiên phần mềm hạ tầng có sẵn'],
], [2300, 3200, 3571]))
A(('h2', '2.5. Nguồn dữ liệu đo và bộ dữ liệu thử nghiệm'))
A(('p', 'Khi triển khai thực tế tại hộ gia đình, thiết bị phần cứng là một cảm biến dòng điện (CT clamp) kẹp tại dây pha của aptomat tổng, chẳng hạn bộ đo Shelly EM hoặc mạch ESP32 cài đặt firmware ESPHome. Thiết bị này đọc công suất tổng theo chu kỳ vài giây và định kỳ đẩy từng batch mẫu đo qua kết nối HTTPS lên API Gateway. Do nhóm không lắp đặt phần cứng trên lưới điện thật trong phạm vi môn học, luồng dữ liệu đầu vào được giả lập bằng công cụ REFIT replayer.'))
A(('p', 'Bộ dữ liệu REFIT [@refit] ghi lại công suất tiêu thụ thực tế của các hộ gia đình tại Vương quốc Anh liên tục trong khoảng hai năm với chu kỳ lấy mẫu 8 giây, bao gồm cả kênh tổng của toàn nhà lẫn kênh đo riêng của từng thiết bị. Công cụ REFIT replayer là một script Python đọc tuần tự các file CSV của REFIT rồi gửi từng batch qua API Gateway bằng đúng REST endpoint, header xác thực API key thiết bị và `Idempotency-Key` như một cảm biến phần cứng, đồng thời hỗ trợ tùy chọn tua nhanh tốc độ phát khi chạy demo. Nhờ giao tiếp hoàn toàn qua hợp đồng API ở biên, các service phía sau gateway xử lý gói tin từ replayer và từ thiết bị thật theo cùng một luồng duy nhất. Trên các sơ đồ kiến trúc, REFIT replayer được biểu diễn ở vị trí nguồn phát dữ liệu bên ngoài kèm chú thích rõ đây là bộ phát lại từ dataset công khai.'))

A(('h1', 'CHƯƠNG 3. PHÂN TÍCH VÀ THIẾT KẾ KIẾN TRÚC'))
A(('h2', '3.1. Tổng quan kiến trúc'))
A(('p', 'Nhóm mô tả kiến trúc hệ thống theo mô hình C4 của Simon Brown [@c4] ở ba cấp độ: sơ đồ Context xác định ranh giới giữa WattPrint với người dùng và các dịch vụ ngoại vi, sơ đồ Container thể hiện các khối phần mềm triển khai độc lập cùng cơ chế truyền thông giữa chúng, và sơ đồ Component đi sâu vào các module bên trong từng service. Cấp độ thứ tư của C4 (Code) được lược bỏ vì cấu trúc lớp và giao diện hàm đã thể hiện trực tiếp trong mã nguồn cùng tài liệu đặc tả OpenAPI. Hình 3.1 trình bày bức tranh tổng quan của toàn hệ thống trên một trang.'))
A(('p', 'Mọi yêu cầu từ ứng dụng người dùng (Expo, Next.js) cũng như luồng dữ liệu từ REFIT replayer đều đi vào hệ thống qua một cổng duy nhất là API Gateway (Envoy). Sau bước kiểm tra chữ ký JWT hoặc định tuyến theo tiền tố, gateway chuyển tiếp request vào năm service nghiệp vụ phía sau. Trên sơ đồ, năm service được sắp xếp từ trái sang phải theo chiều biến đổi dữ liệu: `nilm`, `core`, `insight`, `copilot`, `text2sql`, trong đó `nilm` đặt đứng trước `core` vì `core` gọi `nilm` tách phụ tải ngay trong bước nhận batch mẫu đo. Cách bố trí này giúp cả bốn chiều gọi đồng bộ (`core → nilm`, `insight → core`, `copilot → insight`, `copilot → text2sql`) đều chỉ nối hai khối nằm cạnh nhau và tạo thành một đồ thị có hướng không chu trình: bên cần số liệu chủ động gọi bên nắm giữ số liệu, còn các thông báo thay đổi trạng thái đi theo chiều thuận qua RabbitMQ. Về lưu trữ, mỗi service sở hữu một database logic riêng trên cùng cụm PostgreSQL 18 (kết hợp TimescaleDB cho hai database chuỗi thời gian), trong khi chỉ mục vector của `copilot` và `text2sql` đặt trên một Qdrant dùng chung.'))
A(('fig', '00-overview', 'Hình 3.1. Kiến trúc tổng quan của WattPrint. Mũi tên liền là lời gọi đồng bộ, mũi tên đứt là sự kiện bất đồng bộ qua RabbitMQ', 25.0, 12.0))
A(('h2', '3.2. Bối cảnh hệ thống'))
A(('p', 'Ở cấp độ System Context (Hình 3.2), toàn bộ nền tảng WattPrint được nhìn như một hộp đen đặt giữa hai nhóm người dùng, nguồn phát dữ liệu công suất và năm hệ thống ngoài đã liệt kê tại mục 2.1. Thiết kế ở cấp độ này chốt hai nguyên tắc bảo mật tại biên hệ thống. Về quản lý định danh, WattPrint không tự lưu trữ mật khẩu người dùng mà ủy quyền hoàn toàn luồng đăng nhập cho Keycloak, đồng thời liên kết với Google Identity khi người dùng chọn đăng nhập bằng tài khoản Google. Về bảo vệ dữ liệu hộ gia đình, nhà cung cấp LLM được xếp nằm ngoài vành đai tin cậy (`trust boundary`), do đó mọi prompt gửi ra ngoài đều phải đi qua lớp lọc ẩn thông tin cá nhân (BR9).'))
A(('fig', '01-system-context', 'Hình 3.2. Sơ đồ System Context của WattPrint', 22.0, 13.9))
A(('h2', '3.3. Tách hệ thống thành các service'))
A(('h3', '3.3.1. Tiêu chí tách service'))
A(('p', 'Để tránh việc chia nhỏ hệ thống một cách tùy tiện làm phát sinh các lời gọi mạng chằng chịt, nhóm phân rã ứng dụng monolith hiện tại dựa trên ba tiêu chí kỹ thuật xếp theo thứ tự ưu tiên giảm dần:'))
A(('ol', [
 '**Quyền sở hữu dữ liệu (Data ownership).** Dữ liệu vận hành gốc (hồ sơ hộ, mẫu đo công suất, hóa đơn), dữ liệu chạy mô hình học máy, dữ liệu phân tích thống kê, dữ liệu hội thoại AI và bộ danh mục ngữ nghĩa cho Text-to-SQL (metric, glossary, mô tả cột) thuộc về các miền nghiệp vụ tách biệt. Miền sau chỉ cần đọc kết quả đầu ra của miền trước chứ không ghi đè chéo lên nhau. Đây là tiêu chí quyết định hàng đầu vì mỗi microservice cần toàn quyền kiểm soát schema dữ liệu của riêng mình [@newman].',
 '**Đặc thù tải (Workload).** Mô hình NILMFormer chạy trên thư viện PyTorch tiêu tốn nhiều CPU và bộ nhớ RAM theo từng đợt. Luồng ingest dữ liệu từ cảm biến đòi hỏi độ trễ thấp và tốc độ ghi ổn định. Các thuật toán phân tích và dự báo chủ yếu quét dữ liệu theo lô (batch) hoặc chạy theo lịch định kỳ. Trong khi đó, luồng hỏi đáp của Copilot dành phần lớn thời gian chờ phản hồi I/O mạng từ LLM bên ngoài, còn công cụ Text-to-SQL vừa chờ LLM lập kế hoạch vừa có tiến trình nền tính toán lại vector embedding mỗi khi quản trị viên cập nhật catalog.',
 '**Cô lập lỗi (Fault isolation).** Dịch vụ LLM bên ngoài có thời gian phản hồi biến thiên lớn và dễ gặp lỗi mạng, vì vậy cần tách riêng để sự cố ở nhánh trợ lý AI không làm nghẽn luồng ghi nhận số liệu của cảm biến hay làm chậm màn hình tra cứu hóa đơn. Tương tự, khi mô hình NILM quá tải, hệ thống vẫn phải tiếp nhận và lưu an toàn các mẫu đo mới từ công tơ rồi đánh dấu chờ xử lý sau. Nếu công cụ Text-to-SQL gặp sự cố, trợ lý Copilot vẫn duy trì được hội thoại nhờ các công cụ tra cứu cố định từ service phân tích.',
]))
A(('p', 'Riêng việc tách công cụ truy vấn ngôn ngữ tự nhiên khỏi `copilot` thành một service `text2sql` độc lập còn xuất phát từ hai lý do thực tế của dự án. Một mặt, hệ thống này vốn là một ứng dụng hoàn chỉnh có sẵn (`ai-agent-superset-standalone`) với cấu trúc cơ sở dữ liệu catalog và tiến trình đồng bộ chỉ mục riêng, nên đóng gói thành một service giao tiếp qua API giúp giữ nguyên kiến trúc mã nguồn gốc thay vì phải cắt ghép vào trong `copilot`. Mặt khác, việc tách riêng giúp nhóm vận hành có thể chỉnh sửa định nghĩa metric, từ điển thuật ngữ và chạy đồng bộ lại vector mà không ảnh hưởng tới luồng quản lý hội thoại của người dùng cuối.'))
A(('h3', '3.3.2. Các phương án đã cân nhắc'))
A(('p', 'Từ ba tiêu chí trên, nhóm đặt lên bàn cân bốn phương án phân rã từ hạt thô (hai service) đến hạt mịn (trên bảy service) như trình bày ở Bảng 3.1 và quyết định chọn phương án C.'))
A(('table', 'Bảng 3.1. Các phương án tách service', ['Phương án', 'Cách chia', 'Nhận xét'], [
 ['A. Hai service', 'Gộp core với insight. Gộp nilm với copilot', 'Không đáp ứng yêu cầu tối thiểu ba service nghiệp vụ của đề bài. Cách gộp này còn nhốt chung hai thành phần có đặc tính tài nguyên đối lập vào một tiến trình: nilm ngốn CPU và RAM cho PyTorch, còn copilot chủ yếu chờ I/O mạng từ LLM'],
 ['B. Bốn service', 'core, nilm, insight, copilot (nhúng Text-to-SQL vào trong copilot)', 'Buộc phải tháo rời mã nguồn của ứng dụng Text-to-SQL sẵn có để ghép vào copilot, đồng thời trộn lẫn các bảng quản lý catalog ngữ nghĩa với bảng lịch sử chat. Mỗi khi sửa cấu hình catalog hoặc nâng cấp luồng hội thoại đều phải triển khai lại chung một service'],
 ['C. Năm service (chọn)', 'core, nilm, insight, copilot, text2sql', 'Mỗi service làm chủ một miền dữ liệu, một kiểu tải và một phạm vi chịu lỗi rõ ràng. Service text2sql tái sử dụng trọn vẹn mã nguồn sẵn có, chỉ viết thêm lớp kết nối định danh và phân quyền. Quy mô năm service vẫn vừa sức nhóm ba người nhờ tận dụng được một service hoàn chỉnh'],
 ['D. Bảy service trở lên', 'Tách nhỏ thêm billing, device, alert, notification', 'Mỗi service mới chỉ quản lý một vài bảng dữ liệu nhưng làm tăng số lượng database, số chặng gọi mạng và chi phí cấu hình. Riêng nghiệp vụ tính hóa đơn (billing) cần truy vấn trực tiếp các bảng tổng hợp chuỗi thời gian của core, nếu tách rời sẽ phát sinh truyền tải dữ liệu lớn qua mạng mà không mang lại lợi ích độc lập thực sự'],
], [2000, 2800, 4271]))
A(('h3', '3.3.3. Năm service sau khi tách'))
A(('p', 'Bảng 3.2 tổng hợp chức năng, kho dữ liệu riêng và các đích gọi ra của năm service theo phương án đã chọn. Thứ tự các dòng trong bảng bám sát đường đi của dữ liệu qua sáu nhóm nghiệp vụ ở Bảng 2.2.'))
A(('table', 'Bảng 3.2. Service, trách nhiệm, dữ liệu riêng và đối tượng gọi tới', ['Service', 'Trách nhiệm', 'Dữ liệu riêng', 'Gọi tới'], [
 ['core', 'Quản lý hồ sơ hộ gia đình, thành viên, mã mời, ghép nối công tơ, thiết bị, ingest batch mẫu đo, biểu giá 5 bậc và tính hóa đơn chính thức. Giữ vai trò `source of truth` cho dữ liệu vận hành', 'core_db (TimescaleDB)', 'nilm'],
 ['nilm', 'Chạy inference mô hình NILMFormer tách công suất từng thiết bị, hiệu chỉnh tham số theo hộ, quản lý phiên bản model', 'nilm_db và volume chứa trọng số model', 'Không gọi service nào'],
 ['insight', 'Duy trì read model tiêu thụ theo giờ, phát hiện bất thường và phụ tải chạy ngầm, dự báo hóa đơn và bậc giá, quản lý ngân sách, so sánh nhóm hộ, mô phỏng what-if, đo kiểm M&V, công bố view chỉ đọc cho text2sql', 'insight_db (TimescaleDB)', 'core, Open-Meteo'],
 ['copilot', 'Điều phối hỏi đáp tự nhiên, phát gợi ý chủ động, lọc PII và chống prompt injection (guardrail), kiểm chứng số liệu (verifier), truy xuất RAG, xếp hạng theo phản hồi, gửi thông báo, thống kê token, điều phối saga kế hoạch tiết kiệm', 'copilot_db, collection Qdrant', 'insight, text2sql, LLM, Expo Push, Telegram'],
 ['text2sql', 'Giải đáp câu hỏi tự do về số liệu: quản lý catalog (metric, glossary, mô tả bảng cột), tìm kiếm ngữ nghĩa, gọi LLM lập query plan, biên dịch ra SQL, chạy truy vấn chỉ đọc trên view của insight và che PII trên tập kết quả', 'text2sql_db (catalog, phiên truy vấn), collection Qdrant', 'LLM. Đọc view của insight_db'],
], [1100, 4300, 2100, 1571]))
A(('p', 'Từ Bảng 3.2, có bốn quyết định phân định ranh giới cần làm rõ. Về nghiệp vụ tính tiền, hóa đơn chính thức được đặt tại `core` vì cần tính trực tiếp trên chuỗi mẫu đo gốc và phiên bản biểu giá để giữ tính nhất quán tuyệt đối với `source of truth`, trong khi tính năng dự báo hóa đơn cuối tháng chỉ mang tính ước lượng thống kê nên thuộc về `insight`. Về luồng suy luận học máy, `nilm` được thiết kế như một service thuần tính toán (stateless đối với dữ liệu hộ): chỉ nhận mảng công suất tổng rồi trả về kết quả tách tải mà không gọi sang bất kỳ service nào khác, trở thành điểm nút lá của đồ thị phụ thuộc. Với trợ lý AI, `copilot` không truy cập thẳng vào cơ sở dữ liệu vận hành của `core` mà lấy toàn bộ số liệu qua `insight` và `text2sql` để bảo vệ hiệu năng cho luồng ghi gốc (chi tiết tại mục 3.7). Cuối cùng, việc cho phép `text2sql` mở kết nối chỉ đọc tới các view do `insight` công bố là ngoại lệ có kiểm soát duy nhất đối với nguyên tắc cô lập database giữa các service.'))
A(('p', 'Tổng hợp lại, toàn bộ giao tiếp đồng bộ giữa các service chỉ gồm bốn cạnh có hướng: `core → nilm`, `insight → core`, `copilot → insight` và `copilot → text2sql`. Do đồ thị này không chứa bất kỳ chu trình nào (`circular dependency`), sự cố ngừng hoạt động tại một service chỉ ảnh hưởng cục bộ tới các luồng gọi trực tiếp vào nó mà không gây khóa chết dây chuyền.'))
A(('h2', '3.4. Các khối triển khai'))
A(('p', 'Hình 3.3 thể hiện sơ đồ Container ở cấp độ triển khai. Bên cạnh năm service nghiệp vụ do nhóm phát triển, hệ thống sử dụng năm phần mềm hạ tầng mã nguồn mở: Envoy làm cổng API Gateway, Keycloak quản lý định danh và cấp phát token, RabbitMQ làm message broker, PostgreSQL lưu trữ dữ liệu quan hệ cùng chuỗi thời gian, và Qdrant lưu trữ chỉ mục vector. Toàn bộ cụm phía server gồm đúng mười container, kết hợp với hai ứng dụng client (Expo và Next.js) chạy độc lập bên ngoài. Trong mỗi service nghiệp vụ, nhóm gom cả HTTP router, message consumer, tiến trình đẩy sự kiện (`OutboxRelay`) và các tác vụ chạy theo lịch vào chung một process dưới dạng background task gắn với vòng đời (`lifespan`) của FastAPI. Cách đóng gói này giúp tiết kiệm đáng kể bộ nhớ RAM khi chạy demo trên một máy tính cá nhân mà không phải bật thêm hàng loạt container worker phụ. Dù chạy bằng Docker Compose ở môi trường bài tập, mỗi service đều đã tách riêng Dockerfile, nhận toàn bộ chuỗi kết nối qua biến môi trường và cung cấp hai đầu đo `/health`, `/ready`, sẵn sàng chuyển sang các nền tảng điều phối như Kubernetes mà không cần sửa đổi mã nguồn.'))
A(('p', 'Tuân theo quy ước biểu diễn của mô hình C4 đối với hệ thống hướng sự kiện, mỗi hàng đợi thông điệp được vẽ như một container lưu trữ trung gian thay vì gom chung vào một hộp RabbitMQ duy nhất [@c4]. Do đó, trên Hình 3.3 xuất hiện bốn khối queue màu vàng gồm hai hàng đợi chính (`insight.usage`, `copilot.alerts`) cùng hai DLQ `.dlq` tương ứng.'))
A(('fig', '02-container', 'Hình 3.3. Sơ đồ Container của WattPrint. Nét đứt là message AMQP: mũi tên đi tới queue là bên phát, đi ra khỏi queue là bên tiêu thụ', 25.0, 16.5))
A(('h2', '3.5. Giao tiếp giữa các service'))
A(('h3', '3.5.1. Gọi đồng bộ qua REST'))
A(('p', 'Khi bên gọi cần ngay kết quả để hoàn tất thao tác hiện tại, các service giao tiếp đồng bộ qua giao thức HTTP/REST: `core` gọi `nilm` tách phụ tải khi nhận batch mới, `insight` hỏi `core` thông tin biểu giá cùng danh mục thiết bị, còn `copilot` gọi sang `insight` lấy số liệu phân tích hoặc gọi `text2sql` khi người dùng đặt câu hỏi tự do. Riêng chặng `copilot → text2sql` truyền dữ liệu theo luồng Server-Sent Events (SSE) vì một câu hỏi tự nhiên cần đi qua nhiều bước gọi LLM nối tiếp nhau. Toàn bộ các lời gọi nội bộ này đi trực tiếp qua mạng riêng của Docker Compose chứ không vòng lại qua gateway. Service khởi tạo lời gọi có trách nhiệm chuyển tiếp bộ header ngữ cảnh (`X-User-Id`, `X-User-Roles`, `X-Request-ID`) và tra cứu địa chỉ đích từ biến môi trường. Ở chiều nhận kết quả, thư viện gọi HTTP chung luôn áp đặt ngưỡng timeout, chỉ tự động thử lại (retry) với số lần giới hạn và phân biệt rạch ròi giữa lỗi nghiệp vụ (mã 4xx, giữ nguyên trả về) với lỗi hạ tầng (quá thời gian chờ trả 504, đứt kết nối hoặc circuit breaker đang ngắt trả 503).'))
A(('h3', '3.5.2. Sự kiện bất đồng bộ qua RabbitMQ'))
A(('p', 'Ngược lại, những tác vụ tiếp nối không đòi hỏi bên phát phải đứng chờ kết quả được tách hoàn toàn sang giao tiếp bất đồng bộ qua RabbitMQ (Bảng 3.3). Cụ thể, sau khi `core` lưu xong kết quả tách phụ tải vào cơ sở dữ liệu gốc, luồng ingest có thể trả lời ngay cho cảm biến mà không cần đợi `insight` tính toán lại các bảng tổng hợp. Tương tự, khi `insight` quét thấy một thiết bị chạy bất thường, nó chỉ cần phát thông báo sự kiện chứ không chờ `copilot` gọi LLM biên soạn lời khuyên. Mỗi consumer lắng nghe trên một hàng đợi kiểu quorum queue [@rabbit] được cấu hình giới hạn redelivery tối đa ba lần (`delivery-limit = 3`) trước khi chuyển thông điệp lỗi sang hàng đợi DLQ đi kèm.'))
A(('table', 'Bảng 3.3. Các sự kiện trên exchange `wattprint.events` (kiểu topic)', ['Routing key', 'Bên phát', 'Bên nhận', 'Mục đích'], [
 ['`energy.usage.updated`', 'core', 'insight', 'Báo có kết quả tách phụ tải mới kèm sản lượng điện tổng hợp theo giờ của từng thiết bị'],
 ['`core.device.changed`', 'core', 'insight', 'Đồng bộ thay đổi trong danh mục thiết bị của hộ sang read model bên insight'],
 ['`insight.alert.created`', 'insight', 'copilot', 'Thông báo phát sinh cảnh báo mới để kích hoạt luồng tạo gợi ý tiết kiệm chủ động'],
], [2500, 1100, 1200, 4271]))
A(('p', 'Để bảo đảm không làm rơi sự kiện khi tiến trình gặp sự cố và không cộng trùng số liệu khi broker giao lại thông điệp, mỗi sự kiện đi qua quy trình chín bước kết hợp bảng `outbox` ở đầu phát và bảng `inbox` ở đầu nhận. Hình 3.4 minh họa chi tiết đường đi của sự kiện `energy.usage.updated` từ `core` sang `insight`:'))
A(('ol', [
 'Trong cùng một giao dịch cơ sở dữ liệu (transaction), `core` vừa lưu kết quả tách tải NILM vừa chèn một bản ghi sự kiện vào bảng `outbox`.',
 'Tiến trình nền `OutboxRelay` bên trong `core` định kỳ quét các dòng chưa phát bằng câu lệnh `SELECT ... FOR UPDATE SKIP LOCKED`, nhờ đó dù chạy nhiều bản sao (instance) cũng không bốc trùng một sự kiện.',
 'Relay đẩy message lên exchange `wattprint.events` kèm routing key tương ứng, chờ nhận tín hiệu xác nhận (`publisher confirm`) từ RabbitMQ rồi mới đánh dấu bản ghi trong `outbox` là đã gửi.',
 'Exchange kiểu topic đối chiếu routing key và sao chép message vào mọi hàng đợi có biểu thức binding khớp. Hàng đợi `insight.usage` đăng ký nhận cả hai nhánh `energy.usage.*` và `core.device.*`.',
 'RabbitMQ phân phối message tới consumer của `insight`. Nếu quá trình xử lý ném ra ngoại lệ, consumer gửi tín hiệu `nack` để broker phát lại (redeliver).',
 'Khi nhận message, consumer tra cứu mã `message_id` trong bảng `inbox`. Nếu mã này đã tồn tại thì bỏ qua ngay, còn nếu chưa có thì cập nhật read model và ghi `message_id` vào `inbox` trong cùng một transaction, sau đó mới gửi `ack`.',
 'Trường hợp một message bị giao lại quá ba lần mà vẫn thất bại, quorum queue tự động chuyển tiếp nó sang dead-letter exchange `wattprint.dlx`.',
 'Exchange `wattprint.dlx` định tuyến message lỗi vào hàng đợi lưu trữ `insight.usage.dlq` để bảo toàn dữ liệu và giải phóng hàng đợi chính.',
 'Nhóm vận hành kiểm tra nội dung lỗi trên giao diện quản trị RabbitMQ, khắc phục nguyên nhân gốc rồi đẩy message từ DLQ quay lại `insight.usage` để xử lý bù.',
]))
A(('p', 'Sự kết hợp giữa hai bảng phụ trợ giải quyết trọn vẹn bài toán độ tin cậy trên kênh truyền bất đồng bộ. Nếu service vừa ghi database xong liền gọi hàm publish trực tiếp lên broker mà sập nguồn ở giữa hai lệnh, `insight` sẽ vĩnh viễn thiếu mất đợt dữ liệu đó. Mẫu Transactional Outbox [@richardson] triệt tiêu nguy cơ này bằng tính nguyên tử của giao dịch SQL. Ở đầu bên kia, cơ chế giao ít nhất một lần (at-least-once) của RabbitMQ khiến một gói tin có thể đến tay consumer nhiều lần khi mạng chập chờn. Việc kiểm tra khóa duy nhất trong bảng `inbox` biến thao tác tiêu thụ thành idempotent, giúp mỗi sự kiện chỉ tác động vào read model đúng một lần duy nhất.'))
A(('fig', 'x6-dynamic-messaging-rabbitmq', 'Hình 3.4. Vòng đời một sự kiện qua RabbitMQ: từ bảng outbox, qua exchange và quorum queue tới inbox hoặc DLQ', 25.0, 10.5))
A(('h2', '3.6. Luồng nghiệp vụ nhiều bước và xử lý lỗi giữa chừng'))
A(('p', 'Đề bài yêu cầu thiết kế ít nhất một luồng nghiệp vụ đi qua nhiều service có cơ chế xử lý khi gãy đổ giữa chừng. Trong WattPrint có hai luồng như vậy, và nhóm áp dụng hai chiến lược phục hồi khác nhau tùy thuộc vào việc dữ liệu ở bước đầu tiên có thể hủy bỏ (rollback) hay bắt buộc phải giữ lại.'))
A(('h3', '3.6.1. Ingest dữ liệu sensor và chạy inference NILM'))
A(('p', 'Mỗi khi nhận một batch mẫu đo từ công tơ, `core` lần lượt kiểm tra API key thiết bị, trạng thái ghép nối của công tơ với hộ gia đình và tính liên tục của dải thời gian (BR2, BR3). Sau khi ghi chuỗi công suất tổng vào bảng dữ liệu thô, `core` gọi đồng bộ sang `nilm` để tách phụ tải từng thiết bị. Nếu `nilm` phản hồi trong thời gian cho phép, `core` lưu ước tính của từng thiết bị, ghi sự kiện vào `outbox` rồi trả mã 201 kèm trạng thái `DONE`. Ngược lại, nếu lời gọi sang `nilm` bị quá hạn (timeout), nhận lỗi 5xx hoặc bị chặn bởi circuit breaker đang mở, `core` tuyệt đối không rollback dữ liệu công suất tổng vừa lưu vì đó là số đo thực tế từ hiện trường, nếu xóa đi sẽ tạo khoảng trống dữ liệu. Thay vào đó, `core` đánh dấu lô dữ liệu ở trạng thái `PENDING_INFERENCE`, trả mã 202 cho thiết bị đo và giao cho một tiến trình nền (`PendingRetrier`) tự động thử lại theo chu kỳ lùi dần 1, 2 và 4 phút. Khi vượt quá năm lần thử lại mà `nilm` vẫn chưa phục hồi, lô dữ liệu được chuyển sang trạng thái `FAILED` đồng thời phát cảnh báo tới nhóm vận hành (Hình 3.5).'))
A(('fig', 'x2-dynamic-ingest-nilm', 'Hình 3.5. Luồng ingest dữ liệu sensor và chạy inference NILM, giữ trạng thái PENDING_INFERENCE khi nilm không phản hồi', 25.0, 14.0))
A(('h3', '3.6.2. Kích hoạt kế hoạch tiết kiệm'))
A(('p', 'Khi người dùng đồng ý áp dụng một gợi ý tiết kiệm do AI đề xuất, `copilot` đứng ra điều phối một giao dịch Saga gồm hai bước gọi sang `insight`. Ở bước thứ nhất, `copilot` yêu cầu `insight` chốt đường cơ sở tiêu thụ (baseline M&V) để làm mốc đối chiếu sau này. Nếu hộ gia đình chưa tích lũy đủ 14 ngày dữ liệu theo quy tắc BR5, `insight` từ chối ngay với mã 422 và luồng kết thúc sớm. Khi bước một thành công, `copilot` thực hiện bước thứ hai là cập nhật hạn mức ngân sách tháng theo mục tiêu của kế hoạch. Tùy theo phản hồi của bước hai, bộ điều phối Saga rẽ theo ba nhánh xử lý (Hình 3.6). Nếu bước hai thành công, kế hoạch chuyển sang trạng thái `ACTIVE`. Nếu bị `insight` từ chối bởi lỗi nghiệp vụ 4xx, `copilot` thực thi giao dịch bù trừ (compensate) theo thứ tự ngược bằng cách gọi API xóa bản ghi baseline vừa tạo ở bước một rồi đánh dấu kế hoạch là `CANCELLED`. Trường hợp gặp lỗi hạ tầng như timeout 504, `copilot` chưa thể kết luận yêu cầu đặt ngân sách đã được `insight` ghi nhận hay chưa nên tạm giữ kế hoạch ở trạng thái `PENDING`, chờ tiến trình đối soát nền (`reconciler`) truy vấn lại để chốt hoàn tất hoặc bù trừ sau.'))
A(('p', 'Điểm mấu chốt của thiết kế Saga này nằm ở việc tách bạch lỗi nghiệp vụ và lỗi hạ tầng. Mã lỗi 4xx khẳng định chắc chắn bước hai bị từ chối trước khi làm thay đổi dữ liệu, cho phép hoàn tác bước một ngay lập tức. Ngược lại, lỗi mạng hay timeout mang tính bất định, nếu vội vàng chạy lệnh bù trừ ngay có thể dẫn tới trạng thái lệch giữa hai service.'))
A(('fig', 'x5-dynamic-saving-plan-saga', 'Hình 3.6. Luồng kích hoạt kế hoạch tiết kiệm theo mẫu Saga: thành công, bù trừ ngược khi gặp lỗi 4xx và giữ PENDING khi timeout', 24.0, 14.0))
A(('h2', '3.7. Dữ liệu'))
A(('p', 'Toàn bộ dữ liệu quan hệ và chuỗi thời gian của hệ thống được bố trí trên một máy chủ PostgreSQL 18 chia thành sáu cơ sở dữ liệu độc lập: `core_db`, `nilm_db`, `insight_db`, `copilot_db`, `text2sql_db` và `keycloak_db`. Mỗi database được cấp phát một tài khoản truy cập (DB role) riêng biệt, không một service nào có quyền kết nối sang database của service khác, ngoại trừ một kênh chỉ đọc duy nhất dành cho `text2sql` trình bày ở cuối mục này. Cách tổ chức này giúp nhóm giữ tổng số container trong giới hạn mười container của môi trường demo nhưng vẫn tuân thủ chặt chẽ mẫu thiết kế Database per Service [@newman]. Khi chuyển sang môi trường thực tế cần mở rộng quy mô, từng database có thể tách sang máy chủ vật lý riêng chỉ bằng cách thay đổi chuỗi kết nối trong biến môi trường.'))
A(('p', 'Trên máy chủ PostgreSQL 18, extension TimescaleDB được kích hoạt tại `core_db` (quản lý bảng hypertable mẫu đo gốc, các tầng continuous aggregate theo phút, giờ, ngày cùng chính sách nén và xóa dữ liệu quá hạn) và tại `insight_db` (lưu read model tiêu thụ). Đối với nhu cầu tìm kiếm tương đồng theo ngữ nghĩa, hệ thống sử dụng một container Qdrant làm kho lưu trữ vector duy nhất, chia thành hai collection tách biệt: `copilot_knowledge_v1` lưu vector của kho tài liệu RAG bên `copilot`, và `text2sql_semantics_v1` lưu chỉ mục tìm kiếm danh mục của `text2sql`. Toàn bộ văn bản gốc của tài liệu lẫn định nghĩa catalog vẫn nằm trong PostgreSQL của từng service sở hữu, vì vậy nếu Qdrant gặp sự cố mất dữ liệu thì chỉ mục vector vẫn có thể tái tạo đầy đủ. Nhóm chọn Qdrant thay cho extension `pgvector` vì ứng dụng Text-to-SQL kế thừa đã tích hợp sẵn Qdrant để kết hợp tìm kiếm vector với tìm kiếm toàn văn (hybrid search) trong cùng một truy vấn, và việc quy về một vector store duy nhất giúp giảm gánh nặng vận hành.'))
A(('p', 'Khi đã khóa quyền truy cập chéo ở tầng cơ sở dữ liệu, nhu cầu sử dụng dữ liệu liên service được giải quyết qua hai cơ chế chuẩn:'))
A(('ul', [
 '**Đồng bộ bản sao qua sự kiện theo mẫu CQRS.** Service `insight` duy trì một read model lưu sản lượng tiêu thụ đã tổng hợp theo giờ, được cập nhật bất đồng bộ mỗi khi nhận sự kiện từ `core` [@richardson]. Nhờ tách biệt này, `core` tập trung tối ưu cho luồng ghi tần suất cao và giữ vai trò `source of truth`, còn `insight` tổ chức lại cấu trúc bảng chuyên phục vụ các truy vấn phân tích phức tạp.',
 '**Truy vấn trực tiếp qua REST API.** Đối với những dữ liệu cấu hình nhỏ hoặc đòi hỏi tính tức thời cao, service cần thông tin sẽ gọi API của service sở hữu, điển hình là `insight` gọi sang `core` để lấy bảng giá điện hiện hành và danh sách thiết bị của hộ.',
]))
A(('p', 'Cấu trúc phân tách dữ liệu trên cũng là nền tảng để thiết kế cơ chế bảo mật cho tính năng Text-to-SQL. Nếu cho phép LLM tự sinh câu lệnh SQL rồi thực thi trực tiếp trên cơ sở dữ liệu vận hành của `core`, một câu lệnh sai cú pháp hoặc bị tấn công prompt injection có thể làm lộ dữ liệu của hộ gia đình khác hoặc làm treo bảng ghi mẫu đo. Service `text2sql` khóa chặt rủi ro này bằng ba lớp bảo vệ xếp chồng nhau:'))
A(('ol', [
 '**LLM không trực tiếp viết SQL.** Mô hình ngôn ngữ chỉ được phép trả về một kế hoạch truy vấn (query plan) có cấu trúc, tham chiếu tới mã định danh (ID) của các metric, bảng và cột đã được quản trị viên khai báo trong catalog. Bộ biên dịch (`sqlglot` compiler) của `text2sql` kiểm tra kế hoạch này rồi tự dựng câu lệnh `SELECT`, bọc tên định danh và truyền tham số qua biến ràng buộc (bind parameter), bảo đảm câu lệnh gửi xuống database không chứa bất kỳ đoạn mã SQL tự do nào từ LLM.',
 '**Chỉ truy vấn trên các view phân tích của insight.** Danh mục catalog của `text2sql` chỉ đăng ký các view chỉ đọc do `insight` công bố bên trong `insight_db`. Kết nối cơ sở dữ liệu của `text2sql` sử dụng tài khoản `text2sql_ro` chỉ có duy nhất quyền `SELECT` trên tập view này, luôn thực thi trong giao dịch `READ ONLY` kèm giới hạn thời gian chạy `statement_timeout` là 5 giây và giới hạn số dòng trả về.',
 '**Cô lập dữ liệu hộ gia đình ngay tại tầng view.** Mọi view công bố trong `insight_db` đều gắn điều kiện lọc `WHERE home_id = current_setting(\'app.home_id\', true)::bigint`. Trước khi chạy câu lệnh đã biên dịch, bộ thực thi (executor) của `text2sql` lấy định danh người dùng từ header `X-User-Id` do `copilot` truyền sang để gán biến phiên `app.home_id` ngay trong giao dịch hiện tại, tuyệt đối không lấy mã hộ từ nội dung câu hỏi của người dùng. Nếu biến phiên này chưa được thiết lập, view tự động trả về tập rỗng (BR9).',
]))
A(('p', 'Việc cho phép `text2sql_ro` đọc view trên `insight_db` là ngoại lệ duy nhất trong nguyên tắc cô lập dữ liệu của toàn hệ thống. Nhóm chấp nhận ngoại lệ này vì tập view hoạt động như một hợp đồng giao tiếp hẹp do `insight` làm chủ: `insight` có thể thay đổi cấu trúc bảng vật lý bên dưới mà không làm gãy `text2sql` chừng nào giữ nguyên chữ ký các cột trên view. Cùng với thiết kế này, các bảng dữ liệu trong bản monolith ban đầu cũng được phân bổ lại về đúng database đích theo Bảng 3.2: nhóm bảng cảnh báo, dự báo và M&V chuyển về `insight_db`, bảng nhật ký chạy mô hình (`inference_run`) chuyển về `nilm_db`, các bảng hội thoại và văn bản gốc của tài liệu RAG chuyển về `copilot_db`, còn cột vector nhúng được tách sang Qdrant.'))
A(('h2', '3.8. Gateway và bảo mật'))
A(('p', 'Tầng cổng vào của hệ thống sử dụng Envoy Proxy được cấu hình tĩnh trong file `envoy.yaml`. Đúng theo nguyên tắc thiết kế SOA của đề bài, gateway chỉ đảm nhiệm định tuyến lưu lượng và thực thi các chính sách kiểm soát ở biên, hoàn toàn không chứa logic nghiệp vụ. Toàn bộ các bước kiểm tra tại đây đều tận dụng các bộ lọc (filter) dựng sẵn của Envoy:'))
A(('ul', [
 'Định tuyến theo tiền tố đường dẫn `/api/core/`, `/api/insight/`, `/api/copilot/`, `/api/nilm/` (chỉ mở cho quyền admin) và `/api/text2sql/` (chỉ mở cho admin để cấu hình catalog), trong đó mỗi nhánh route áp dụng ngưỡng timeout và chính sách retry riêng. Người dùng cuối khi hỏi số liệu tự nhiên luôn đi qua `copilot` chứ không gọi thẳng vào `text2sql`. Tại gateway, chính sách tự động retry chỉ bật cho phương thức `GET` khi gặp lỗi đứt kết nối, không áp dụng cho `POST` nhằm tránh tạo bản ghi trùng.',
 'Bộ lọc `jwt_authn` xác thực chữ ký số RS256, trường `issuer` và `audience` của access token dựa trên tập khóa công khai (JWKS) tải định kỳ từ Keycloak [@envoy]. Khi token hợp lệ, Envoy trích xuất các trường định danh (`sub` và danh sách role) để gán vào hai header nội bộ `X-User-Id` và `X-User-Roles`, đồng thời xóa sạch mọi header trùng tên do phía client cố tình gửi lên, nhờ vậy các service phía sau có thể tin tưởng tuyệt đối vào thông tin định danh trên header.',
 'Bộ lọc giới hạn tốc độ gọi (`local_ratelimit`), giới hạn dung lượng tối đa của phần thân request và tự động gắn mã vết `x-request-id` cho từng yêu cầu để liên kết log xuyên suốt các service.',
 'Riêng đường dẫn nhận batch mẫu đo từ cảm biến không áp dụng bộ lọc kiểm tra JWT vì thiết bị đo phần cứng không chạy luồng đăng nhập người dùng. Yêu cầu đi vào nhánh này được chuyển thẳng tới `core` để tự xác thực bằng API key của thiết bị và kiểm tra trạng thái ghép nối công tơ (BR2).',
]))
A(('p', 'Các quy tắc phân quyền gắn với ngữ cảnh nghiệp vụ như kiểm tra người dùng có thuộc hộ gia đình đang truy vấn hay không, tài khoản có đang sở hữu gói thuê bao Pro hay có quyền quản trị viên hay không đều do từng service phía sau tự thực thi. Ở tầng mạng container, cả năm service nghiệp vụ đều không mở cổng (publish port) ra máy chủ host, đảm bảo mọi lưu lượng từ bên ngoài bắt buộc phải đi qua cổng kiểm soát của Envoy.'))
A(('h2', '3.9. Công nghệ sử dụng'))
A(('p', 'Với quy mô nhóm ba thành viên, nguyên tắc xuyên suốt khi chọn công nghệ là giữ số lượng công cụ ở mức tối giản và ưu tiên tận dụng tính năng cấu hình sẵn của phần mềm hạ tầng thay vì tự viết lại mã nguồn (Bảng 3.4). Toàn bộ năm service phía backend thống nhất viết bằng Python, còn hai ứng dụng phía người dùng phát triển bằng TypeScript.'))
A(('table', 'Bảng 3.4. Công nghệ sử dụng và lý do chọn', ['Lớp', 'Chọn', 'Lý do'], [
 ['Gateway', 'Envoy 1.40', 'Cung cấp sẵn các bộ lọc kiểm tra JWT, giới hạn tốc độ (rate limit), gắn request ID, quản lý timeout và retry chỉ bằng file cấu hình YAML. Là proxy hiệu năng cao đạt chuẩn CNCF graduated'],
 ['Identity', 'Keycloak 26', 'Hỗ trợ đầy đủ chuẩn OIDC, cấp phát JWT và liên kết sẵn với Google Identity. Lưu trữ dữ liệu vào `keycloak_db` trên cụm PostgreSQL chung nên không tốn thêm container cơ sở dữ liệu riêng'],
 ['Database', 'PostgreSQL 18, TimescaleDB 2.31', 'Đáp ứng đồng thời cả lưu trữ quan hệ truyền thống lẫn xử lý chuỗi thời gian cường độ cao trên cùng một hệ quản trị, tránh phải vận hành thêm một hệ cơ sở dữ liệu time-series riêng biệt'],
 ['Vector store', 'Qdrant 1.20', 'Được ứng dụng Text-to-SQL tích hợp sẵn để truy vấn kết hợp vector và full-text. Tận dụng làm kho vector chung cho cả RAG của copilot, phân tách bằng hai collection độc lập'],
 ['Text-to-SQL', 'Service text2sql: sqlglot, presidio, LLM qua API tương thích OpenAI', 'Tái sử dụng trọn vẹn ứng dụng sẵn có. Bộ biên dịch sqlglot dựng câu lệnh SQL từ kế hoạch nên không cho LLM tự viết SQL, kết hợp thư viện Presidio ẩn PII trên bảng kết quả'],
 ['Message broker', 'RabbitMQ 4, quorum queue', 'Hỗ trợ trực tiếp cơ chế đếm số lần giao lại (`delivery-limit`) và định tuyến sang dead-letter exchange ngay ở tầng hàng đợi, không phải tự lập trình bộ đếm retry'],
 ['Service', 'Python 3.14, FastAPI, SQLAlchemy async, Alembic', 'Kế thừa trực tiếp nền tảng mã nguồn của bản monolith. FastAPI hỗ trợ xử lý bất đồng bộ (async/await) và tự động xuất tài liệu đặc tả OpenAPI từ kiểu dữ liệu Pydantic'],
 ['Messaging trong service', 'FastStream', 'Cho phép khai báo hàm consumer với cú pháp tương đồng như viết route của FastAPI, tự động sinh tài liệu AsyncAPI và cung cấp sẵn broker giả lập trong bộ nhớ để viết unit test'],
 ['Gọi HTTP và fault tolerance', 'httpx, tenacity. Circuit breaker và bulkhead tự viết trong thư viện chung', 'Các thư viện circuit breaker sẵn có của Python không hỗ trợ gọn mô hình asyncio thuần, nên nhóm tự hiện thực khoảng 30 dòng mã chuẩn xác và dùng `asyncio.Semaphore` làm vách ngăn bulkhead [@nygard]'],
 ['Mã nguồn', 'Monorepo uv workspace: `services/` và `libs/common`', 'Quản lý toàn bộ phụ thuộc bằng một file khóa (`uv.lock`) duy nhất. Các thành phần chịu lỗi, định dạng log, bảng outbox và inbox chỉ cần viết một lần trong `libs/common`'],
 ['Kiểm tra', 'ruff, pytest, Postman với Newman, GitHub Actions', 'Tự động hóa trọn vẹn quy trình kiểm tra mã tĩnh, chạy unit test, đóng gói image, dựng cụm Docker Compose và bắn bộ kiểm thử Postman trên pipeline CI'],
], [1700, 2800, 4571]))
A(('p', 'Để tránh làm phình bộ nhớ của cụm container khi chạy demo, nhóm chủ động không đưa vào các bộ công cụ giám sát nặng như Prometheus, Grafana, Loki hay Jaeger, đồng thời không tách container worker riêng hay cơ sở dữ liệu riêng cho Keycloak. Thay vào đó, mỗi service xuất trực tiếp các dòng log định dạng JSON có đính kèm trường `request_id` ra luồng `stdout`, cho phép nhóm tra cứu và lần vết toàn bộ đường đi của một yêu cầu qua nhiều service bằng lệnh `docker compose logs`.'))
A(('h2', '3.10. Thành phần bên trong từng service'))
A(('p', 'Năm sơ đồ Component dưới đây mở hộp từng service nghiệp vụ để làm rõ cách phân chia module nội bộ và các điểm kết nối ra bên ngoài. Những mũi tên không ghi nhãn giao thức biểu thị lời gọi hàm trực tiếp bên trong cùng một tiến trình Python. Các sơ đồ tuân theo bảng màu thống nhất: màu xanh lá là các module nghiệp vụ do nhóm viết, màu tím là phần mềm hạ tầng có sẵn, màu vàng là hàng đợi thông điệp, màu xanh ngọc là kho lưu trữ dữ liệu, màu cam là hệ thống bên ngoài và đường nét đứt biểu diễn luồng sự kiện bất đồng bộ.'))
A(('p', 'Bên trong **core** (Hình 3.7), tầng giao tiếp HTTP được chia thành ba cụm router tương ứng với ba mảng dữ liệu gốc: quản lý hồ sơ hộ cùng thiết bị, nhận batch mẫu đo từ cảm biến và tra cứu hóa đơn. Khi có gói dữ liệu đo gửi lên, `IngestService` kiểm tra quy tắc liên tục rồi gọi qua tầng `Repositories` để ghi đồng thời cả mẫu đo công suất lẫn bản ghi sự kiện vào `core_db` trong cùng một giao dịch. Hai tiến trình nền chạy song song trong vòng đời ứng dụng gồm `OutboxRelay` (đẩy sự kiện mới lên RabbitMQ) và `PendingRetrier` (quét các batch đang ở trạng thái chờ để gọi lại mô hình tách tải). Toàn bộ giao tiếp đi ra ngoài của `core` đều hội tụ về một cổng duy nhất là module `NilmClient`, nơi bọc sẵn các lớp bảo vệ timeout, retry và circuit breaker.'))
A(('p', 'Cấu trúc của **nilm** (Hình 3.8) gọn hơn vì chỉ tập trung cho bài toán suy luận học máy. Tầng HTTP tách riêng API chạy inference (phục vụ `core`) và API quản lý danh mục model (chỉ mở cho quản trị viên). Khi khởi động container, `ModelLoader` đọc file trọng số từ ổ đĩa nạp sẵn vào bộ nhớ RAM một lần duy nhất. Mỗi yêu cầu tách phụ tải đi qua `InferenceEngine` để chạy mô hình NILMFormer, sau đó qua `Calibrator` để nhân hệ số hiệu chỉnh theo từng hộ gia đình. Để ngăn nguy cơ tràn bộ nhớ khi có nhiều batch dồn về cùng lúc, tầng API đặt một vách ngăn bulkhead (`asyncio.Semaphore`) giới hạn số luồng suy luận chạy đồng thời.'))
A(('p', 'Tại **insight** (Hình 3.9), dữ liệu đi vào theo hai nhánh độc lập. Nhánh bất đồng bộ bắt đầu từ `Usage consumer` lắng nghe hàng đợi RabbitMQ, kiểm tra chống trùng qua bảng `inbox` rồi cập nhật vào read model tiêu thụ theo giờ. Ngay sau khi dữ liệu mới được ghi nhận, bộ `Detectors` chạy các quy tắc kiểm tra phụ tải bất thường, nguy cơ vượt ngân sách và thời điểm chạm bậc giá để sinh cảnh báo, đồng thời đẩy sự kiện `insight.alert.created` ra ngoài qua `OutboxRelay`. Nhánh đồng bộ cung cấp các REST API phục vụ màn hình biểu đồ phân tích, dự báo hóa đơn, mô phỏng what-if và quản lý đường cơ sở M&V. Ở tầng cơ sở dữ liệu, `insight` định nghĩa và công bố tập view chỉ đọc đã gắn sẵn bộ lọc theo hộ gia đình để phục vụ riêng cho `text2sql` (mục 3.7).'))
A(('p', 'Service **copilot** (Hình 3.10) tổ chức thành hai luồng xử lý tương ứng với hai chiều tương tác của trợ lý năng lượng. Ở chiều hỏi đáp chủ động từ người dùng (pull), yêu cầu đi vào `Chat API`, vượt qua chốt chặn `Guardrail` (kiểm tra thuê bao gói Pro, lọc prompt injection và ẩn thông tin cá nhân) trước khi tới bộ điều phối `Orchestrator`. Tại đây, mô hình ngôn ngữ lựa chọn công cụ lấy dữ liệu: gọi các hàm cố định qua `InsightClient` (lấy dự báo, kết quả what-if, so sánh tháng) hoặc chuyển câu hỏi tự do sang `Text2sqlClient`, kết hợp với `RAG retriever` tìm kiếm tài liệu hướng dẫn trên Qdrant. Trước khi gửi câu trả lời về client, module `Verifier` đối chiếu lại mọi con số, đơn vị đo và nguồn trích dẫn với kết quả gốc của công cụ. Ở chiều gợi ý chủ động (push), `Alert consumer` đón sự kiện cảnh báo từ RabbitMQ, chuyển qua `Ranker` để chấm điểm ưu tiên dựa trên lịch sử phản hồi của hộ và kiểm tra khung giờ nghỉ, rồi giao cho `Notifier` phát thông báo qua Expo Push hoặc Telegram. Module `Saga orchestrator` đảm nhận việc điều phối luồng hai bước khi người dùng kích hoạt kế hoạch tiết kiệm (mục 3.6.2).'))
A(('p', 'Service thứ năm là **text2sql** (Hình 3.11), mở hai nhóm giao diện gồm `Chat API` (trả kết quả từng bước qua SSE cho `copilot`) và `Catalog API` (phục vụ quản trị viên khai báo metric, từ điển thuật ngữ và quy tắc nghiệp vụ). Khi nhận một câu hỏi về số liệu, `Pipeline` chuẩn hóa lại câu chữ theo từ điển chuyên ngành, gọi `Semantic retriever` truy tìm các metric và cột bảng liên quan nhất trên Qdrant, rồi yêu cầu LLM lập kế hoạch truy vấn theo ID. Tiếp đó, `Compiler` chuyển đổi kế hoạch thành câu lệnh `SELECT` chuẩn xác để `Executor` mở giao dịch chỉ đọc, gán biến phiên `app.home_id` và thực thi trên các view của `insight_db`. Tập kết quả trả về được `PII masker` quét ẩn thông tin nhạy cảm một lần nữa trước khi gửi về `copilot`, trong khi `Ingestion worker` chạy ngầm để cập nhật lại chỉ mục vector trên Qdrant mỗi khi quản trị viên chỉnh sửa catalog.'))
A(('p', 'Một điểm thiết kế đáng chú ý trong sự phối hợp giữa `copilot` và `text2sql` là cách phân định trạng thái hội thoại. Toàn bộ lịch sử cuộc trò chuyện của người dùng cuối chỉ lưu tại `copilot_db` dưới sự quản lý của `copilot`. Service `text2sql` không lưu hội thoại người dùng mà chỉ ghi nhận **phiên truy vấn** (`query session`): kế hoạch truy vấn đã lập, danh sách metric đã chọn, câu lệnh SQL đã chạy và trạng thái tạm dừng khi câu hỏi có nhiều cách kết nối bảng (join path) cần người dùng xác nhận. Nhờ lưu lại ngữ cảnh kỹ thuật này, `text2sql` xử lý chính xác được các câu hỏi nối tiếp kiểu "còn tháng trước thì sao?". Ở lượt hỏi số liệu đầu tiên trong một cuộc trò chuyện, `text2sql` khởi tạo phiên truy vấn mới và trả mã phiên về cho `copilot` lưu kèm vào bản ghi `ai_tool_call`. Ở các lượt hỏi sau trong cùng cuộc chat, `copilot` đính kèm lại mã phiên đó. Nhờ vậy, người dùng cuối chỉ nhìn thấy một mạch hội thoại liền lạc duy nhất trên ứng dụng.'))
