A(('h1', 'CHƯƠNG 4. ĐÁNH ĐỔI VÀ RỦI RO CỦA KIẾN TRÚC'))
A(('h2', '4.1. Các quyết định chính và đánh đổi'))
A(('p', 'Không có thiết kế kiến trúc nào đạt điểm tối đa ở mọi tiêu chí. Mỗi quyết định phân rã hay chọn công nghệ ở Chương 3 đều là kết quả cân nhắc giữa tính độc lập của service, độ tin cậy khi vận hành và quỹ thời gian của nhóm ba người. Bảng 4.1 tổng hợp mười một quyết định kiến trúc trọng tâm cùng những đánh đổi kỹ thuật mà nhóm chủ động chấp nhận.'))
A(('table', 'Bảng 4.1. Quyết định kiến trúc và đánh đổi', ['Quyết định', 'Lý do', 'Đánh đổi chấp nhận'], [
 ['Phân rã thành năm service thay vì giữ kiến trúc monolith', 'Tách biệt rõ ranh giới sở hữu dữ liệu, đặc thù tải CPU/I-O và phạm vi chịu lỗi của từng mảng nghiệp vụ, đồng thời đáp ứng yêu cầu của học phần', 'Phát sinh độ trễ truyền thông qua mạng nội bộ, xuất hiện các trạng thái lỗi một phần (partial failure) và việc gỡ lỗi phức tạp hơn so với một tiến trình duy nhất'],
 ['Dừng ở quy mô năm service thay vì tách nhỏ thành bảy service trở lên', 'Giữ số lượng container, cơ sở dữ liệu và các chặng gọi mạng ở ngưỡng nhóm ba sinh viên có thể vận hành và kiểm thử thấu đáo', 'Phạm vi trách nhiệm của một số service lớn hơn, điển hình là `core` đảm nhận cả quản lý hồ sơ hộ gia đình lẫn tính hóa đơn tiền điện'],
 ['Tách riêng công cụ Text-to-SQL thành service `text2sql`', 'Tái sử dụng nguyên vẹn mã nguồn ứng dụng Text-to-SQL sẵn có, tách biệt dữ liệu catalog ngữ nghĩa và tiến trình tạo embedding khỏi luồng hội thoại', 'Tăng thêm một container service và một chặng gọi mạng SSE khi xử lý câu hỏi số liệu tự do. Cần duy trì lớp tích hợp định danh và phân quyền khi nâng cấp ứng dụng gốc'],
 ['Cho phép `text2sql` đọc trực tiếp các view công bố trên `insight_db`', 'Truy vấn phân tích chạy thẳng trên dữ liệu đã tổng hợp của `insight` mà không phải xây thêm một tầng API truyền tải dữ liệu trung gian. Điều kiện lọc theo hộ nằm ngay tại view của database', 'Tạo ra một ngoại lệ có kiểm soát đối với nguyên tắc Database per Service. Tập view trở thành hợp đồng cứng giữa hai bên: nếu `insight` sửa cấu trúc view thì `text2sql` phải đồng bộ lại catalog'],
 ['Sử dụng duy nhất Qdrant làm kho lưu trữ vector', 'Ứng dụng Text-to-SQL đã tích hợp sẵn Qdrant cho bài toán tìm kiếm kết hợp (hybrid search). Dùng chung một hạ tầng vector store cho cả `copilot` và `text2sql` qua hai collection riêng', 'Phải vận hành và sao lưu thêm một hệ lưu trữ ngoài PostgreSQL. Dữ liệu văn bản gốc và vector nằm ở hai nơi khác nhau nên cần tiến trình worker đồng bộ khi nội dung thay đổi'],
 ['Thiết kế đồ thị gọi đồng bộ một chiều không chu trình', 'Loại bỏ hoàn toàn nguy cơ phụ thuộc vòng (`circular dependency`). Sự cố tại một service chỉ ảnh hưởng tới các service gọi trực tiếp vào nó', 'Trợ lý `copilot` không đọc thẳng dữ liệu từ `core` mà phải đi qua `insight` hoặc `text2sql`, chấp nhận thêm một bước trung gian đổi lấy sự cô lập tải cho database gốc'],
 ['Truyền sự kiện bất đồng bộ qua RabbitMQ cho các luồng cập nhật liên miền', 'Giúp luồng ghi của `core` và luồng quét cảnh báo của `insight` hoàn tất nhanh mà không phải chờ bên nhận xử lý xong, đồng thời có sẵn cơ chế DLQ bảo toàn thông điệp lỗi', 'Dữ liệu trên read model của `insight` có độ trễ ngắn so với `core` (eventual consistency). Mỗi service phải duy trì thêm bảng `outbox`, `inbox` và tiến trình relay'],
 ['Đặt sáu cơ sở dữ liệu logic trên cùng một máy chủ PostgreSQL 18', 'Giữ tổng số container của toàn hệ thống ở mức mười để chạy mượt trên một máy demo cá nhân nhưng vẫn cô lập quyền truy cập bằng các DB role riêng biệt', 'Container PostgreSQL trở thành điểm lỗi đơn (single point of failure) ở tầng vật lý và các database phải chia sẻ chung tài nguyên CPU, bộ nhớ của một instance'],
 ['Thống nhất một ngôn ngữ Python và dùng chung thư viện `libs/common`', 'Chỉ cần viết và kiểm thử một lần cho các cơ chế phức tạp như circuit breaker, bulkhead, chuẩn hóa log JSON, outbox và inbox', 'Toàn bộ các service backend gắn chặt vào hệ sinh thái Python. Mỗi thay đổi bất tương thích trong `libs/common` đều đòi hỏi kiểm thử lại trên cả năm service'],
 ['Gom API, consumer và các tác vụ nền vào chung một process mỗi container', 'Đơn giản hóa cấu hình khởi chạy Docker Compose, tiết kiệm bộ nhớ RAM và gom toàn bộ log của một service về một luồng xuất duy nhất', 'Không thể nhân bản (scale) riêng tầng xử lý HTTP API và tầng consumer nền. Khi tác vụ nền chạy nặng có thể cạnh tranh chu kỳ CPU với các request API'],
 ['Tự hiện thực circuit breaker và bulkhead trong thư viện nội bộ', 'Các thư viện circuit breaker phổ biến trên Python chưa hỗ trợ gọn nhẹ mô hình bất đồng bộ `asyncio` thuần của FastAPI', 'Nhóm phải tự viết bộ unit test kiểm chứng kỹ các trạng thái đóng/mở mạch và không có sẵn giao diện biểu đồ giám sát mạch như các thư viện thương mại'],
], [2500, 3200, 3371]))
A(('h2', '4.2. Rủi ro còn lại và hướng xử lý'))
A(('p', 'Từ các đánh đổi trên, nhóm rà soát những kịch bản lỗi có khả năng xảy ra trong quá trình vận hành và thiết lập sẵn phương án giảm thiểu ở tầng kiến trúc (Bảng 4.2). Các ngưỡng cấu hình chi tiết cùng số liệu đo kiểm thực tế khi tiêm lỗi sẽ được trình bày ở chương kiểm thử độ tin cậy.'))
A(('table', 'Bảng 4.2. Rủi ro và hướng xử lý', ['Rủi ro', 'Biểu hiện', 'Hướng xử lý'], [
 ['Service `nilm` quá tải CPU/RAM hoặc ngừng phản hồi', '`core` không lấy được kết quả tách phụ tải ngay trong lúc xử lý request ingest từ cảm biến', 'Giữ nguyên dữ liệu công suất thô đã lưu, đánh dấu lô dữ liệu là `PENDING_INFERENCE` rồi trả mã 202, sau đó dùng tiến trình nền thử lại theo chu kỳ lùi dần. Kết hợp circuit breaker ở `core` và vách ngăn bulkhead ở `nilm`'],
 ['Nhà cung cấp LLM phản hồi quá chậm hoặc đứt kết nối', 'Các yêu cầu hỏi đáp của Copilot bị treo lâu, có nguy cơ làm cạn kiệt worker nếu không giới hạn', 'Đặt ngưỡng timeout 20 giây cho lời gọi LLM, tự động ngắt circuit breaker khi lỗi liên tiếp và trả mã 503 rõ ràng. Nhờ tách service riêng, dashboard và luồng ingest hoàn toàn không bị ảnh hưởng'],
 ['Thông điệp sự kiện bị phát lặp lại hoặc lỗi xử lý liên tục', 'Read model của `insight` có nguy cơ cộng trùng sản lượng điện hoặc làm tắc nghẽn hàng đợi chính', 'Dùng bảng `inbox` kiểm tra khóa `message_id` để bỏ qua bản tin trùng, bảng `outbox` chống rơi sự kiện khi ghi DB và tự động đẩy thông điệp lỗi quá ba lần sang hàng đợi DLQ để xử lý thủ công'],
 ['Số liệu trên read model của `insight` tạm thời lệch so với `core`', 'Biểu đồ phân tích hiển thị tổng kWh chênh lệch nhẹ so với con số trên hóa đơn trong vài giây đầu hoặc khi có message nằm ở DLQ', 'Quy định mọi nghiệp vụ tính hóa đơn chính thức luôn truy vấn trực tiếp từ `core_db`. Bổ sung kịch bản đồng bộ bù (reconciliation) cho read model khi khôi phục message từ DLQ'],
 ['Mô hình LLM tự bịa ra con số tiền điện hoặc công suất sai thực tế', 'Người dùng nhận được thông tin tư vấn sai lệch so với dữ liệu đo đạc của gia đình', 'Áp dụng nguyên tắc mọi con số đều do công cụ tính toán xác định. Module `Verifier` kiểm tra chéo số liệu, đơn vị và nguồn trích dẫn trước khi cho phép hiển thị câu trả lời (BR8)'],
 ['Rò rỉ thông tin định danh cá nhân hoặc lộ dữ liệu sang hộ khác', 'Prompt gửi ra LLM chứa tên, địa chỉ người dùng hoặc truy vấn Text-to-SQL đọc nhầm dữ liệu của nhà bên cạnh', 'Module `Guardrail` ẩn PII trước khi gọi LLM và `text2sql` quét Presidio trên kết quả trả về. Câu lệnh SQL do bộ biên dịch dựng, chạy bằng role chỉ đọc trên các view đã khóa cứng điều kiện `app.home_id`'],
 ['Service `text2sql` chọn nhầm metric hoặc gặp câu hỏi đa nghĩa', 'Câu lệnh SQL chạy hợp lệ về mặt cú pháp nhưng không phản ánh đúng ý định câu hỏi của người dùng', 'Khi phát hiện câu hỏi mơ hồ hoặc có nhiều đường kết nối bảng chưa rõ ràng, `text2sql` tạm dừng phiên và hỏi lại người dùng thay vì tự đoán. Câu trả lời cuối cùng luôn đính kèm truy vấn đã chạy để đối chiếu'],
 ['Service `text2sql` hoặc kho vector Qdrant ngừng hoạt động', 'Không thực hiện được truy vấn số liệu tự do và không tìm kiếm được đoạn văn bản trong kho tri thức RAG', 'Circuit breaker tại `copilot` ngắt nhanh đường gọi sang `text2sql` và tự động chuyển sang trả lời bằng bộ tool cố định của `insight`. Chỉ mục Qdrant có thể tái tạo bất cứ lúc nào từ văn bản gốc trong PostgreSQL'],
 ['Container PostgreSQL gặp sự cố dừng đột ngột', 'Toàn bộ các service mất kết nối cơ sở dữ liệu tại cùng một thời điểm', 'Chấp nhận trong phạm vi môi trường demo trên một máy. Khi triển khai thực tế sẽ tách các database quan trọng sang cụm máy chủ riêng có cấu hình bản sao dự phòng (streaming replication)'],
], [2300, 2700, 4071]))
